import { NextRequest, NextResponse } from "next/server";

export const dynamic = "force-dynamic";

const knownPreviewSlugs = new Set([
  "home", "about", "books", "bookshelf", "children", "entertainment", "games",
  "learning", "quizzes", "services", "contact", "authors", "policies", "privacy",
  "terms", "read-ebooks", "subscribe",
]);

// A real JPEG is used because WhatsApp, Facebook and many messaging apps do not
// reliably render SVG Open Graph images. The page title and description remain
// route-specific in the HTML metadata generated by the root layout.
export async function GET(request: NextRequest, context: { params: Promise<{ slug: string }> }) {
  const { slug } = await context.params;
  const safeSlug = String(slug || "").toLowerCase();
  const destination = new URL("/homepage_hero%20(1).jpeg", request.url);
  destination.searchParams.set("share", knownPreviewSlugs.has(safeSlug) ? safeSlug : safeSlug.slice(0, 80));
  return NextResponse.redirect(destination, { status: 302 });
}
